      "q5": "最大支持什么规模的文档？",
      "a5": "最大支持 50 张幻灯片的单个 Google Slides™ 文档，满足绝大多数日常使用场景。",
      "q6": "是否 100% 复刻原始文档排版和样式？",
      "a6": "由于每种语言表达相同语义的字符数完全不同，TransLay 使用 AI 和技术手段最大限度地还原原始文档的样式和排版，但仍然无法保证 100% 还原。您可以利用 20 页的免费额度，使用您的真实文档来验证样式和排版还原效果，再决定是否购买使用。",
      "q7": "如何联系技术支持？",
