      "privacy": {
        "title": "TransLay 隐私政策",
        "last_updated": "最后更新：2026-04-23",
        "intro": [
          "我们把“少收集、少保存、少暴露”当作 TransLay 的基本原则。您使用 TransLay 时，我们只处理让翻译、登录、订阅和售后能够正常运转所必需的最少信息；凡是不该收集的，不该长期保存的，我们都尽量不碰。本隐私政策说明 TransLay 如何处理这些信息。"
        ],
        "sections": [
          {
            "title": "1. 我们坚持的隐私原则",
            "paragraphs": [
              "TransLay 的核心原则很简单：只为了完成您主动发起的服务而处理必要信息，不做与服务无关的收集，不做广告用途，不做用户画像，也不做行为分析。尤其是，对您文档中的正文、译文、comments 和 notes，我们遵循严格的最小化原则，不会把这些内容长期留存在数据库、缓存或应用日志里。"
            ]
          },
          {
            "title": "2. 为了提供服务，我们会处理哪些最少信息",
            "paragraphs": [
              "我们可能会处理 Google 账户基础信息，例如 Google 账户标识、邮箱、显示名称和头像，用于确认您的身份、把订阅和额度绑定到正确账户、显示当前登录账户，并提供售后支持。",
              "我们只会在您主动开始翻译任务后，处理您明确选择翻译的 Google Slides™ 内容，用于完成该次翻译和写回。",
              "我们还会处理显示任务进度、结算额度、核查账单问题和提供支持所必需的最少任务与额度信息，例如 Task ID、任务状态、页数使用情况、时间戳以及有限的故障排查元数据。",
              "如果您购买套餐或额度，我们会处理确认权益所必需的最少订单与订阅信息，例如支付状态、订单号、购买或退款时间以及订阅状态。完整银行卡信息由 Paddle 处理，不由我们保存。",
              "对于网站会话，我们只使用维持官网和订阅页面正常工作所必需的最少会话信息。Cookie 仅保存一个不透明的 session id，不会直接保存您的邮箱、套餐或配额等可读明文信息。"
            ]
          },
          {
            "title": "3. 我们不会保存或收集什么",
            "paragraphs": [
              "我们不会把您的文档正文、翻译结果、comments 或 notes 的明文保存在数据库、缓存或日志中。翻译任务结束后，这些内容会立即从我们的数据库和缓存中删除，不会继续作为您的文档备份保留，因此请您自行保管好翻译后的目标文档。",
              "如果您之后对同一份文档再次发起相同语言的翻译，我们会将其视为一个新的独立任务。由于我们不会保留此前的文档内容或译文，这类任务不会直接复用上一次结果，也会按当次任务规则完整计费。",
              "我们不会把您的信息用于广告、广告归因、用户画像或行为分析。我们不会出售您的数据，也不会因为您使用了 TransLay，就去跟踪您在其他网站、其他文档或其他产品中的行为。",
              "我们不会保存您的完整银行卡号、银行账户号或其他完整支付凭证。付款由 Paddle 处理，我们只接收订单和售后所需的最少结果信息。"
            ]
          },
          {
            "title": "4. 为什么需要 Google 权限",
            "paragraphs": [
              "TransLay 是一个 Google Workspace™ 插件。要在 Google Slides™ 中正常工作，我们只申请当前产品范围直接需要的权限。",
              "Google Slides™ 权限用于读取您要翻译的演示文稿内容，并把译文写回原文件或目标文件。没有这项权限，TransLay 就无法读取内容或完成写回。",
              "Google Drive™ 权限用于定位当前演示文稿、在“输出到新文件”模式下创建用户自己的副本、把目标文件放到合适位置，并管理任务执行期间所需的临时访问。没有这项权限，某些复制和写回流程就无法稳定运行。",
              "Google Drive™ file 权限用于帮助我们尽量把文件操作限制在当前工作流涉及的文件上。",
              "Google Workspace™ 容器界面权限用于让 TransLay 侧边栏显示在 Google Slides™ 中。",
              "外部请求权限用于让插件安全地与 TransLay 后端通信，完成翻译任务、权益刷新、登录和订阅相关流程。",
              "Google 账户邮箱与头像权限用于登录识别、显示当前账户、绑定订阅以及处理售后支持。"
            ]
          },
          {
            "title": "5. 如何授予这些权限",
            "paragraphs": [
              "当您通过 Google Workspace Marketplace 安装 TransLay 后，首次在 Google Slides™ 中打开并启动它时，Google 会提示您完成授权流程。通常情况下，您安装插件后，打开任意 Google Slides™ 演示文稿，进入“扩展程序”，启动 TransLay，然后按照提示跳转到 Google 权限确认页面。",
              "在确认页面，请使用您准备与 TransLay 配套使用的 Google 账户登录，如果 Google 提供“全选”复选框，请勾选所需权限，然后点击“允许”或“确认”。如果不授予这些必要权限，TransLay 将无法正常读取文档、执行翻译、创建目标文件、写回结果，或完成登录与订阅相关流程。"
            ]
          },
          {
            "title": "6. 我们如何使用这些信息",
            "paragraphs": [
              "这些信息只会被用于完成您请求的翻译、显示当前登录状态、绑定订阅与额度、处理账单与退款、回复售后问题、防止滥用，以及保障服务稳定运行。我们不会将这些信息用于广告、用户画像、营销推荐或行为分析。我们也不会使用您的文档内容来训练我们自己的模型。"
            ]
          },
          {
            "title": "7. 第三方服务",
            "paragraphs": [
              "为了运行 TransLay，我们会在必要时依赖少量第三方服务，例如 Google Workspace™ 与 Google Cloud 用于托管、文档访问和服务运行，AI 与云服务提供商用于翻译处理，Paddle 用于支付、税务和退款流程。这些服务仅在提供当前功能所必需的范围内参与处理。"
            ]
          },
          {
            "title": "8. 保留与删除",
            "paragraphs": [
              "我们的目标是在最短时间内保留尽量少的信息。与翻译内容相关的正文、译文、comments 和 notes 会在任务结束后立即从数据库和缓存中删除。账户绑定、订阅、订单和合规所必需的少量信息，可能会在确有必要时继续保留，以便确认权益、处理退款或响应合法请求。",
              "如果您希望删除与账户相关的个人信息，或希望了解仍然保留了哪些最少记录，可以联系 <strong>support@example.com</strong>。请注意，如果您要求删除用于证明和恢复订阅权益所必需的记录，我们之后可能无法再为您恢复相应权益。"
            ]
          },
          {
            "title": "9. 您的权利与选择",
            "paragraphs": [
              "您可以随时停止使用 TransLay，也可以取消订阅、退出登录，或联系我们提出隐私相关请求。在适用法律赋予您访问、更正、删除或限制处理等权利的情况下，我们会按适用规则处理有效请求。"
            ]
          },
          {
            "title": "10. 政策更新与联系方式",
            "paragraphs": [
              "如果产品形态、支付流程或法律义务发生变化，我们可能更新本隐私政策。更新后的版本会发布在官网相关页面。若您对隐私、数据处理或安全问题有任何疑问，请发送邮件至 <strong>support@example.com</strong>。"
            ]
          }
        ]
      }
