              "そのページで、TransLay と一緒に使いたい Google アカウントでログインし、必要権限を選択して、Allow または Confirm をクリックしてください。これらの権限がないと、文書の読み取り、翻訳実行、対象ファイルの作成、書き戻し、サインインや購読フローの完了ができません。"
