      "a3": "月付订阅默认不退款。年度承诺计划默认不退款；但首次购买年度承诺的用户，如在购买后 14 天内提出申请，且自该笔付款起 0 页已用，可享受一次性退款。按量购买的额度，未使用部分可申请全额退款，已使用部分不可退款。若发生计费错误、未经授权付款、重大服务故障，或法律另有要求时，我们也会按适用规则处理退款。",
