      "title": "您的演示",
      "title_accent": "任意语言",
      "title_end": "原样呈现",
      "subtitle": "TransLay 以 LLM 级别的翻译质量和像素级的排版保真度，翻译 Google Slides™ —— 每一种字体、每一个文本框，都与原稿一致。"
